// === ПРОКСИ: один аккаунт, несколько sticky-портов ===
// У proxy.market каждый порт pool.proxy.market:N — отдельный исходящий IP.
// Порт 10000 20.08.2026 ловил CONNECT 503 только на *.sudrf.ru — в пул не берём.
// На каждый вызов вебхука берём случайный порт и тем же URL идём и в поиск, и в карточку.
// Повтор внутри одного вызова нельзя: шлюз Caddy ~30с, а мёртвый CONNECT часто висит 8–20с.
const PROXY_USER = 'nNzui4dOVx';
const PROXY_PASS = 'zhbVdUF5ZF';
const PROXY_HOST = 'pool.proxy.market';
const PROXY_PORTS = [10001, 10002, 10003, 10004, 10005, 10006, 10007, 10008, 10009, 10010];

function pickProxyPort(requested) {
  const n = Number(requested);
  if (PROXY_PORTS.indexOf(n) !== -1) return n;
  return PROXY_PORTS[Math.floor(Math.random() * PROXY_PORTS.length)];
}

const COURTS = {
  'sovetsky-vrn': 'sovetsky--vrn.sudrf.ru',
  'kominternovsky-vrn': 'kominternovsky--vrn.sudrf.ru',
  'zheleznodorozhny-vrn': 'zheleznodorozhny--vrn.sudrf.ru',
  'levoberezhny-vrn': 'levoberezhny--vrn.sudrf.ru',
  'centralny-vrn': 'centralny--vrn.sudrf.ru',
  'lensud-vrn': 'lensud--vrn.sudrf.ru',
};
// Подтверждено scraper.case_lookup.discover 20.08.2026 на всех 6 сайтах через
// резидентный прокси: имена полей формы одинаковы для всей платформы ГАС
// «Правосудие» этой версии (delo_id 1540005/1540006, delo_table g1_case/u1_case).
const PRODUCTION = {
  civil_first_instance: { delo_id: 1540005, table: 'g1_case', case_number_field: 'g1_case__CASE_NUMBERSS', last_name_field: 'G1_PARTS__NAMESS' },
  criminal_first_instance: { delo_id: 1540006, table: 'u1_case', case_number_field: 'u1_case__CASE_NUMBERSS', last_name_field: 'U1_DEFENDANT__NAMESS' },
};

const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const court_slug = String(body.court_slug || '').trim();
const case_number = String(body.case_number || '').trim();
const last_name = String(body.last_name || '').trim();
const production_type = String(body.production_type || 'civil_first_instance').trim();
const proxyPort = pickProxyPort(body.proxy_port);
const proxy = 'http://' + PROXY_USER + ':' + PROXY_PASS + '@' + PROXY_HOST + ':' + proxyPort;

if (!court_slug || !COURTS[court_slug]) {
  return [{ json: { skipHttp: true, status: 'error', result: `Неизвестный суд '${court_slug}'. Допустимые: ${Object.keys(COURTS).join(', ')}.` } }];
}
if (!case_number && !last_name) {
  return [{ json: { skipHttp: true, status: 'error', result: 'Нужно указать case_number или last_name.' } }];
}
const prod = PRODUCTION[production_type] || PRODUCTION.civil_first_instance;
const domain = COURTS[court_slug];

const qs = {
  name: 'sud_delo', srv_num: '1', name_op: 'r',
  delo_id: String(prod.delo_id), case_type: '0', new: '0', delo_table: prod.table,
};
if (case_number) qs[prod.case_number_field] = case_number;
if (last_name) qs[prod.last_name_field] = last_name;

const baseUrl = `https://${domain}/modules.php`;
return [{ json: { skipHttp: false, searchUrl: baseUrl, baseUrl, qsJson: JSON.stringify(qs), proxy, proxyPort } }];

function stripTags(s) {
  return String(s)
    .replace(/<span[^>]*class=['"]tooltipShow['"][\s\S]*?<\/span>/gi, '')
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&rarr;/g, '->')
    .replace(/\s+/g, ' ')
    .trim();
}

// В песочнице n8n Code node нет глобального класса URL — резолвим вручную.
function resolveUrl(href, base) {
  if (/^https?:\/\//i.test(href)) return href;
  const m = String(base).match(/^(https?:\/\/[^\/]+)/i);
  const origin = m ? m[1] : '';
  return href.startsWith('/') ? origin + href : origin + '/' + href;
}

const NOT_FOUND_MARKERS = ['не обнаружено', 'уточните критерии поиска', 'ничего не найдено', 'не найдено дел'];

const item = $input.first().json;
const baseUrl = $('Подготовить запрос').item.json.baseUrl;
const html = item.data || item.body || (typeof item === 'string' ? item : '') || '';

if (!html) {
  return [{ json: { needsDetail: false, status: 'error', result: 'Сайт суда временно недоступен через прокси (не ответил вовремя). Попробуйте задать вопрос ещё раз.' } }];
}

const lower = html.toLowerCase();
if (NOT_FOUND_MARKERS.some((m) => lower.includes(m))) {
  return [{ json: { needsDetail: false, status: 'not_found', result: 'По заданным критериям дел не найдено. Проверьте номер дела/фамилию или обратитесь на сайт суда напрямую (раздел «Судебное делопроизводство»).' } }];
}

const tableMatch = html.match(/<table[^>]*id=["']tablcont["'][^>]*>([\s\S]*?)<\/table>/i);
if (!tableMatch) {
  return [{ json: { needsDetail: false, status: 'error', result: 'Страница результатов получена, но структура не распознана (сайт суда мог обновить вёрстку).' } }];
}

const rows = [...tableMatch[1].matchAll(/<tr[\s\S]*?<\/tr>/gi)].map((m) => m[0]);
const dataRows = rows.slice(1);
const hits = [];
for (const row of dataRows) {
  const linkMatch = row.match(/<a[^>]*href=(["'])([\s\S]*?)\1[^>]*>([\s\S]*?)<\/a>/i);
  if (!linkMatch) continue;
  const href = linkMatch[2].replace(/&amp;/g, '&');
  const caseNumber = stripTags(linkMatch[3]);
  hits.push({ caseNumber, detailUrl: resolveUrl(href, baseUrl) });
}

if (!hits.length) {
  return [{ json: { needsDetail: false, status: 'not_found', result: 'По заданным критериям дел не найдено.' } }];
}

return [{ json: {
  needsDetail: true,
  detailUrl: hits[0].detailUrl,
  firstCaseNumber: hits[0].caseNumber,
  extraCount: hits.length - 1,
} }];

function stripTags(s) {
  return String(s)
    .replace(/<span[^>]*class=['"]tooltipShow['"][\s\S]*?<\/span>/gi, '')
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&rarr;/g, '->')
    .replace(/\s+/g, ' ')
    .trim();
}

const item = $input.first().json;
const meta = $('Разобрать результаты поиска').item.json;
const html = item.data || item.body || (typeof item === 'string' ? item : '') || '';

if (!html) {
  return [{ json: { status: 'found', result: `Дело ${meta.firstCaseNumber || ''} найдено, но подробная карточка временно недоступна через прокси. Номер дела подтверждён, для деталей загляните на сайт суда или спросите ещё раз чуть позже.`.trim() } }];
}

const blocks = [...html.matchAll(/<table[^>]*id=["']tablcont["'][^>]*>([\s\S]*?)<\/table>/gi)];
const sections = [];
for (const block of blocks) {
  const inner = block[1];
  const rows = [...inner.matchAll(/<tr[\s\S]*?<\/tr>/gi)].map((m) => m[0]);
  if (!rows.length) continue;
  const headerMatch = rows[0].match(/<th[^>]*>([\s\S]*?)<\/th>/i);
  const title = headerMatch ? stripTags(headerMatch[1]) : null;
  const isSectionHeaderRow = title && !/<td/i.test(rows[0]);
  const bodyRows = isSectionHeaderRow ? rows.slice(1) : rows;
  const headerCells = bodyRows.length
    ? [...bodyRows[0].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)].map((m) => stripTags(m[1]))
    : [];
  const looksLikeTable = headerCells.length > 2;
  const kv = [];
  if (looksLikeTable) {
    for (const row of bodyRows.slice(1)) {
      const cells = [...row.matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)].map((m) => stripTags(m[1]));
      if (!cells.some(Boolean)) continue;
      const parts = [];
      headerCells.forEach((h, i) => { if (h && cells[i]) parts.push(`${h}: ${cells[i]}`); });
      if (parts.length) kv.push(parts.join('; '));
    }
  } else {
    for (const row of bodyRows) {
      const cells = [...row.matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)].map((m) => stripTags(m[1]));
      if (cells.length >= 2 && cells[0]) {
        const value = cells.slice(1).filter(Boolean).join(' | ');
        if (value) kv.push(`${cells[0]}: ${value}`);
      }
    }
  }
  if (title && kv.length) sections.push({ title, kv });
}

if (!sections.length) {
  return [{ json: { status: 'error', result: 'Карточка дела получена, но её структура не распознана.' } }];
}

const lines = [`Дело ${meta.firstCaseNumber || ''}`.trim()];
for (const s of sections) {
  lines.push('', s.title);
  for (const r of s.kv) lines.push('  ' + r);
}
if (meta.extraCount > 0) {
  lines.push('', `Найдено ещё ${meta.extraCount} дел(а) по этим критериям — уточните номер дела, чтобы увидеть конкретное.`);
}

return [{ json: { status: 'found', result: lines.join('\n').trim() } }];
